/*
 * The abrupt path of a group of forked arms, whose code starts at
 * groupStart and ends here.  A group completes only when each of its
 * threads has (Specification/basic/evaluation/parallelism.tex, section
 * "Threads and Parallelism"): where arm 0 or a join throws, the handler
 * waits for every arm that was forked, and then throws that exception on.
 * The joins run in the arms' order and each throws what its arm threw,
 * so the exception caught is that of the first arm, in that order, that
 * threw.  An arm that was never forked is not run.  The task locals stay
 * live until the handler has read them.  The table entry is written after
 * the code that it covers, so that a handler inside an arm comes first.
 */
private void joinForkedArms(Label groupStart, String[] tasks, int[] taskVars) {
    final int n = tasks.length;
    Label groupEnd = new Label();
    Label handler = new Label();
    Label done = new Label();

    mv.visitLabel(groupEnd);
    mv.visitJumpInsn(GOTO, done);

    mv.visitLabel(handler);
    int thrown = mv.createCompilerLocal("thrown", "Ljava/lang/Throwable;");
    mv.visitVarInsn(ASTORE, thrown);
    // An error of the JVM itself, as a stack overflow, can leave a forked
    // arm that nothing will run: it is thrown on without the joins.
    Label rethrow = new Label();
    mv.visitVarInsn(ALOAD, thrown);
    mv.visitTypeInsn(INSTANCEOF, "java/lang/VirtualMachineError");
    mv.visitJumpInsn(IFNE, rethrow);
    for (int i = 1; i < n; i++) {
        mv.visitVarInsn(ALOAD, taskVars[i]);
        mv.visitMethodInsn(INVOKEVIRTUAL, tasks[i], "joinIfForked", "()V");
    }
    mv.visitLabel(rethrow);
    mv.visitVarInsn(ALOAD, thrown);
    mv.disposeCompilerLocal(thrown);
    mv.visitInsn(ATHROW);

    mv.visitLabel(done);
    mv.visitTryCatchBlock(groupStart, groupEnd, handler, "java/lang/Throwable");

    // Most recently created first.
    for (int i = 1; i < n; i++)
        mv.disposeCompilerLocal(taskVars[i]);
}

private void genParallelExprs(List<? extends Expr> args, Type domain_type, List<VarCodeGen> vcgs, boolean clearStackAtEnd) {
    final int n = args.size();
    if (n <= 0) return;

    List<Type> domain_types;
    if (NodeUtil.isVoidType(domain_type)) {
        domain_types = new ArrayList<Type>();
        for (int i = 0; i < n; i++)
            domain_types.add(domain_type);
    } else if (args.size() != 1 && domain_type instanceof TupleType) {
        TupleType tdt = (TupleType) domain_type;
        domain_types = tdt.getElements();
    } else {
        domain_types = Collections.singletonList(domain_type);
    }

    String [] tasks = new String[n];
    String [] results = new String[n];
    int [] taskVars = new int[n];

    if (vcgs != null && vcgs.size() != n) {
        System.out.println("vcgs size = " + vcgs.size() + " n = " + n);
        throw sayWhat(args.get(0), "Internal error: number of args does not match number of consumers.");
    }

    // Push arg tasks from right to left, so
    // that local evaluation of args will proceed left to right.
    // IMPORTANT: ALWAYS fork and join stack fashion,
    // ie always join with the most recent fork first.
    for (int i = n-1; i > 0; i--) {
        Expr arg = args.get(i);
        // Make sure arg has type info (we'll need it to generate task)
        Option<Type> ot = NodeUtil.getExprType(arg);
        if (!ot.isSome())
            throw sayWhat(arg, "Missing type information for argument " + arg);
        Type t = ot.unwrap();
        String tDesc = NamingCzar.jvmBoxedTypeDesc(t, component.getName());
        // Find free vars of arg
        List<VarCodeGen> freeVars = getFreeVars(arg);
        BASet<VarType> fvts = fvt.freeVarTypes(arg);

        // Generate descriptor for init method of task
        String init = taskConstructorDesc(freeVars);

        String task = delegate(arg, tDesc, init, freeVars, fvts);
        tasks[i] = task;
        results[i] = tDesc;
        constructWithFreeVars(task, freeVars, init);

        mv.visitInsn(DUP);
        int taskVar = mv.createCompilerLocal(task, // Naming.mangleIdentifier(task),
