        for (int i = 0; i < n; i++) {
            // dup tuple (always, ensure swap will work).
            mv.visitInsn(DUP);

            VarCodeGen vcg = vcgs.get(i);
            /* swap dup'd tuple to TOS -- note assumption that prepareAssignValue pushes 
             * either zero or one item on stack.
